"""Which name means which step."""

from pipeline.steps import Squeeze, Strip, Truncate, Upper

STEPS = {"upper": Upper(), "strip": Strip(), "squeeze": Squeeze()}


def lookup(name: str):
    if ":" in name:
        parts = name.split(":", 1)
        base_name = parts[0]
        arg = parts[1]
        if base_name == "truncate":
            if arg == "":
                raise ValueError("truncate requires a length argument")
            try:
                length = int(arg)
            except ValueError:
                raise ValueError(
                    f"truncate length must be an integer, got {arg!r}"
                )
            return Truncate(length=length)
        # Known step with extra args -- not expected, fall through to KeyError
        raise KeyError(f"no step named {name!r}. Known: {', '.join(sorted(STEPS))}")
    if name not in STEPS:
        raise KeyError(f"no step named {name!r}. Known: {', '.join(sorted(STEPS))}")
    return STEPS[name]

